import React, { useState, useEffect } from 'react';
import { CheckCircleIcon, ExclamationTriangleIcon, InformationCircleIcon, DocumentDuplicateIcon } from '@heroicons/react/24/outline';
import { useNotification } from '../../hooks/useNotification';

const DKIMConfigurationStep = ({ domainId, data, onChange, errors, onNext, onPrev, canGoBack, saving }) => {
  const [dkimSelector, setDkimSelector] = useState(data.dkimSelector || 'default');
  const [keyLength, setKeyLength] = useState(data.keyLength || '2048');
  const [publicKey, setPublicKey] = useState(data.publicKey || '');
  const [privateKey, setPrivateKey] = useState(data.privateKey || '');
  const [dkimRecord, setDkimRecord] = useState(data.dkimRecord || '');
  const [keyGenerated, setKeyGenerated] = useState(data.keyGenerated || false);
  const [emailProvider, setEmailProvider] = useState(data.emailProvider || 'custom');
  const { showNotification } = useNotification();

  // Proveedores de email con configuraciones predefinidas
  const emailProviders = [
    {
      id: 'google',
      name: 'Google Workspace',
      description: 'Configuración automática para Google Workspace',
      selector: 'google',
      instructions: 'Ve a Admin Console > Apps > Google Workspace > Gmail > Authenticate email'
    },
    {
      id: 'microsoft',
      name: 'Microsoft 365',
      description: 'Configuración automática para Microsoft 365',
      selector: 'selector1',
      instructions: 'Ve a Security & Compliance Center > Threat management > Policy > DKIM'
    },
    {
      id: 'sendgrid',
      name: 'SendGrid',
      description: 'Configuración para SendGrid',
      selector: 's1',
      instructions: 'Ve a Settings > Sender Authentication > Domain Authentication'
    },
    {
      id: 'mailgun',
      name: 'Mailgun',
      description: 'Configuración para Mailgun',
      selector: 'mg',
      instructions: 'Ve a Sending > Domains > DKIM'
    },
    {
      id: 'custom',
      name: 'Configuración Personalizada',
      description: 'Generar claves DKIM personalizadas',
      selector: 'default',
      instructions: 'Generaremos las claves DKIM para ti'
    }
  ];

  useEffect(() => {
    // Actualizar datos del paso cuando cambien los valores
    onChange('dkimSelector', dkimSelector);
    onChange('keyLength', keyLength);
    onChange('publicKey', publicKey);
    onChange('privateKey', privateKey);
    onChange('dkimRecord', dkimRecord);
    onChange('keyGenerated', keyGenerated);
    onChange('emailProvider', emailProvider);
  }, [dkimSelector, keyLength, publicKey, privateKey, dkimRecord, keyGenerated, emailProvider]);

  useEffect(() => {
    if (publicKey) {
      generateDKIMRecord();
    }
  }, [publicKey, dkimSelector]);

  const generateDKIMKeys = async () => {
    try {
      // Simular generación de claves DKIM
      showNotification('Generando claves DKIM...', 'info');

      // En una implementación real, esto llamaría a una API para generar las claves
      setTimeout(() => {
        const mockPublicKey = `MIIBIjANBgkqhkiG9w0BAQEFAAOCAQ8AMIIBCgKCAQEA1234567890abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ`;
        const mockPrivateKey = `-----BEGIN PRIVATE KEY-----\nMIIEvQIBADANBgkqhkiG9w0BAQEFAASCBKcwggSjAgEAAoIBAQDXXXXXXXXXXXXX\n...\n-----END PRIVATE KEY-----`;

        setPublicKey(mockPublicKey);
        setPrivateKey(mockPrivateKey);
        setKeyGenerated(true);
        showNotification('Claves DKIM generadas correctamente', 'success');
      }, 2000);

    } catch (error) {
      console.error('Error generating DKIM keys:', error);
      showNotification('Error al generar las claves DKIM', 'error');
    }
  };

  const generateDKIMRecord = () => {
    if (!publicKey) return;

    // Limpiar la clave pública para el registro DNS
    const cleanPublicKey = publicKey.replace(/\s+/g, '');

    const record = `v=DKIM1; k=rsa; p=${cleanPublicKey}`;
    setDkimRecord(record);
  };

  const copyToClipboard = async (text, label) => {
    try {
      await navigator.clipboard.writeText(text);
      showNotification(`${label} copiado al portapapeles`, 'success');
    } catch (error) {
      console.error('Error copying to clipboard:', error);
      showNotification('Error al copiar al portapapeles', 'error');
    }
  };

  const handleProviderChange = (providerId) => {
    setEmailProvider(providerId);
    const provider = emailProviders.find(p => p.id === providerId);
    if (provider) {
      setDkimSelector(provider.selector);

      // Limpiar claves si cambia a un proveedor que no es custom
      if (providerId !== 'custom') {
        setPublicKey('');
        setPrivateKey('');
        setDkimRecord('');
        setKeyGenerated(false);
      }
    }
  };

  const validateDKIMConfig = () => {
    const issues = [];

    if (!dkimSelector) {
      issues.push('Debe especificar un selector DKIM');
    }

    if (emailProvider === 'custom' && !keyGenerated) {
      issues.push('Debe generar las claves DKIM');
    }

    if (emailProvider === 'custom' && !publicKey) {
      issues.push('Falta la clave pública DKIM');
    }

    if (dkimSelector && !/^[a-zA-Z0-9._-]+$/.test(dkimSelector)) {
      issues.push('El selector DKIM contiene caracteres inválidos');
    }

    return issues;
  };

  const validationIssues = validateDKIMConfig();
  const isValid = validationIssues.length === 0;

  const handleNext = () => {
    if (isValid) {
      onNext();
    } else {
      showNotification('Por favor corrige los errores en la configuración DKIM', 'error');
    }
  };

  const selectedProvider = emailProviders.find(p => p.id === emailProvider);

  return (
    <div className="space-y-6">
      {/* Introducción */}
      <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
        <div className="flex items-start">
          <div className="flex-shrink-0">
            <InformationCircleIcon className="h-5 w-5 text-blue-400" />
          </div>
          <div className="ml-3">
            <h3 className="text-sm font-medium text-blue-800">
              Configuración DKIM
            </h3>
            <div className="mt-2 text-sm text-blue-700">
              <p>
                DKIM (DomainKeys Identified Mail) añade una firma digital a tus correos
                para verificar que provienen de tu dominio y no han sido modificados.
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* Selección de proveedor */}
      <div className="bg-white border border-gray-200 rounded-lg p-4">
        <h3 className="text-lg font-medium text-gray-900 mb-4">Proveedor de Email</h3>
        <p className="text-sm text-gray-600 mb-4">
          Selecciona tu proveedor de email para una configuración optimizada:
        </p>

        <div className="space-y-3">
          {emailProviders.map(provider => (
            <label key={provider.id} className="flex items-start p-3 border border-gray-200 rounded-lg hover:bg-gray-50 cursor-pointer">
              <input
                type="radio"
                name="emailProvider"
                value={provider.id}
                checked={emailProvider === provider.id}
                onChange={(e) => handleProviderChange(e.target.value)}
                className="h-4 w-4 text-primary-600 focus:ring-primary-500 border-gray-300 mt-0.5"
              />
              <div className="ml-3">
                <div className="text-sm font-medium text-gray-900">{provider.name}</div>
                <div className="text-sm text-gray-600">{provider.description}</div>
              </div>
            </label>
          ))}
        </div>
      </div>

      {/* Configuración del selector */}
      <div className="bg-white border border-gray-200 rounded-lg p-4">
        <h3 className="text-lg font-medium text-gray-900 mb-4">Selector DKIM</h3>
        <p className="text-sm text-gray-600 mb-4">
          El selector identifica la clave DKIM específica utilizada para firmar los correos:
        </p>

        <div className="max-w-md">
          <label htmlFor="dkimSelector" className="block text-sm font-medium text-gray-700 mb-2">
            Selector
          </label>
          <input
            type="text"
            id="dkimSelector"
            value={dkimSelector}
            onChange={(e) => setDkimSelector(e.target.value)}
            placeholder="ej: default, s1, selector1"
            className="block w-full rounded-md border-gray-300 shadow-sm focus:border-primary-500 focus:ring-primary-500 sm:text-sm"
          />
          <p className="mt-1 text-xs text-gray-500">
            Solo letras, números, puntos, guiones y guiones bajos
          </p>
        </div>
      </div>

      {/* Generación de claves (solo para custom) */}
      {emailProvider === 'custom' && (
        <div className="bg-white border border-gray-200 rounded-lg p-4">
          <h3 className="text-lg font-medium text-gray-900 mb-4">Generación de Claves</h3>

          <div className="mb-4">
            <label htmlFor="keyLength" className="block text-sm font-medium text-gray-700 mb-2">
              Longitud de Clave
            </label>
            <select
              id="keyLength"
              value={keyLength}
              onChange={(e) => setKeyLength(e.target.value)}
              className="block w-32 rounded-md border-gray-300 shadow-sm focus:border-primary-500 focus:ring-primary-500 sm:text-sm"
            >
              <option value="1024">1024 bits</option>
              <option value="2048">2048 bits</option>
              <option value="4096">4096 bits</option>
            </select>
            <p className="mt-1 text-xs text-gray-500">
              Se recomienda 2048 bits para un balance entre seguridad y rendimiento
            </p>
          </div>

          <button
            onClick={generateDKIMKeys}
            disabled={keyGenerated}
            className="inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md shadow-sm text-white bg-primary-600 hover:bg-primary-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {keyGenerated ? 'Claves Generadas' : 'Generar Claves DKIM'}
          </button>
        </div>
      )}

      {/* Claves generadas */}
      {emailProvider === 'custom' && keyGenerated && (
        <div className="bg-white border border-gray-200 rounded-lg p-4">
          <h3 className="text-lg font-medium text-gray-900 mb-4">Claves DKIM</h3>

          {/* Clave privada */}
          <div className="mb-6">
            <div className="flex items-center justify-between mb-2">
              <label className="block text-sm font-medium text-gray-700">
                Clave Privada (para tu servidor de correo)
              </label>
              <button
                onClick={() => copyToClipboard(privateKey, 'Clave privada')}
                className="inline-flex items-center text-sm text-primary-600 hover:text-primary-800"
              >
                <DocumentDuplicateIcon className="h-4 w-4 mr-1" />
                Copiar
              </button>
            </div>
            <textarea
              value={privateKey}
              readOnly
              rows={4}
              className="block w-full rounded-md border-gray-300 bg-gray-50 shadow-sm focus:border-primary-500 focus:ring-primary-500 sm:text-sm font-mono"
            />
            <p className="mt-1 text-xs text-gray-500">
              Guarda esta clave de forma segura. La necesitarás para configurar tu servidor de correo.
            </p>
          </div>

          {/* Clave pública */}
          <div className="mb-4">
            <div className="flex items-center justify-between mb-2">
              <label className="block text-sm font-medium text-gray-700">
                Clave Pública
              </label>
              <button
                onClick={() => copyToClipboard(publicKey, 'Clave pública')}
                className="inline-flex items-center text-sm text-primary-600 hover:text-primary-800"
              >
                <DocumentDuplicateIcon className="h-4 w-4 mr-1" />
                Copiar
              </button>
            </div>
            <textarea
              value={publicKey}
              readOnly
              rows={3}
              className="block w-full rounded-md border-gray-300 bg-gray-50 shadow-sm focus:border-primary-500 focus:ring-primary-500 sm:text-sm font-mono"
            />
          </div>
        </div>
      )}

      {/* Registro DNS */}
      {(emailProvider === 'custom' && dkimRecord) || emailProvider !== 'custom' && (
        <div className="bg-white border border-gray-200 rounded-lg p-4">
          <h3 className="text-lg font-medium text-gray-900 mb-4">Registro DNS DKIM</h3>

          <div className="bg-gray-50 border border-gray-200 rounded-md p-3 mb-4">
            <div className="text-sm text-gray-600 mb-2">Tipo: TXT</div>
            <div className="text-sm text-gray-600 mb-2">
              Nombre: {dkimSelector}._domainkey (o {dkimSelector}._domainkey.tudominio.com)
            </div>
            <div className="text-sm text-gray-600 mb-2">Valor:</div>
            <div className="font-mono text-sm bg-white border border-gray-200 rounded p-2 break-all">
              {emailProvider === 'custom' ? dkimRecord : `Consulta la documentación de ${selectedProvider?.name}`}
            </div>
            {emailProvider === 'custom' && (
              <button
                onClick={() => copyToClipboard(dkimRecord, 'Registro DKIM')}
                className="mt-2 inline-flex items-center text-sm text-primary-600 hover:text-primary-800"
              >
                <DocumentDuplicateIcon className="h-4 w-4 mr-1" />
                Copiar registro
              </button>
            )}
          </div>
        </div>
      )}

      {/* Instrucciones específicas del proveedor */}
      {selectedProvider && selectedProvider.instructions && (
        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
          <div className="flex">
            <InformationCircleIcon className="h-5 w-5 text-yellow-400 flex-shrink-0" />
            <div className="ml-3">
              <h3 className="text-sm font-medium text-yellow-800">
                Instrucciones para {selectedProvider.name}
              </h3>
              <div className="mt-2 text-sm text-yellow-700">
                <p>{selectedProvider.instructions}</p>
                {emailProvider !== 'custom' && (
                  <p className="mt-2">
                    Una vez configurado en {selectedProvider.name}, agrega el registro DNS
                    que te proporcionen en tu proveedor de DNS.
                  </p>
                )}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Validación */}
      {validationIssues.length > 0 && (
        <div className="bg-red-50 border border-red-200 rounded-lg p-3">
          <div className="flex">
            <ExclamationTriangleIcon className="h-5 w-5 text-red-400 flex-shrink-0" />
            <div className="ml-3">
              <h4 className="text-sm font-medium text-red-800">Problemas Detectados</h4>
              <ul className="mt-2 text-sm text-red-700 list-disc list-inside">
                {validationIssues.map((issue, index) => (
                  <li key={index}>{issue}</li>
                ))}
              </ul>
            </div>
          </div>
        </div>
      )}

      {/* Error de validación */}
      {errors.dkimSelector && (
        <div className="text-sm text-red-600">
          {errors.dkimSelector}
        </div>
      )}

      {/* Botones de navegación */}
      <div className="flex justify-between pt-6">
        <button
          onClick={onPrev}
          disabled={!canGoBack}
          className="inline-flex items-center px-4 py-2 border border-gray-300 shadow-sm text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          Anterior
        </button>

        <button
          onClick={handleNext}
          disabled={saving || !isValid}
          className="inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md shadow-sm text-white bg-primary-600 hover:bg-primary-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {saving ? 'Guardando...' : 'Siguiente'}
        </button>
      </div>
    </div>
  );
};

export default DKIMConfigurationStep;
